import { test } from 'node:test';
import * as assert from 'node:assert/strict';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

/**
 * Target Implementation Assumption: 
 * We look for a module exported at './linux-socket-territory-observation.mjs'
 * relative to this test file.
 */
import * as SocketTerritory from './linux-socket-territory-observation.mjs';

test('exact-loopback-tcp-territory', async (t) => {
  const tmpDir = mkdtempSync(join(tmpdir(), 'sock-test-'));

  try {
    // Given: Injected snapshot (mocked as a file artifact)
    const snapshotPath = join(tmpDir, 'snapshot.json');
    const snapshot = {
      namespace: 'ns-0',
      sockets: [{ family: 'AF_INET', protocol: 'TCP', local: '127.0.0.1:80', state: 'LISTEN' }],
      admissibleDenominator: '10'
    };
    writeFileSync(snapshotPath, JSON.stringify(snapshot));

    // When: Observed
    const observation = SocketTerritory.observeLinuxSocketTerritory({
      snapshotPath,
      admissibilityPolicy: { protocol: 'TCP', family: 'AF_INET' }
    });

    // Then: Assertions
    assert.ok(observation, 'Observation must exist');
    assert.strictEqual(typeof observation.capacity, 'object');
    assert.strictEqual(typeof observation.occupancy, 'object');

    // Assert Reduced Exact Fractions
    assert.strictEqual(observation.occupancy.numerator, '1');
    assert.strictEqual(observation.occupancy.denominator, '10');

    // Assert 1/N Share logic
    assert.strictEqual(observation.berthShare.numerator, '1');
    assert.strictEqual(observation.berthShare.denominator, '10');

    // Forbidden check
    assert.throws(() => { if (typeof observation.price !== 'undefined') throw new Error('Price claim forbidden'); });
  } finally {
    rmSync(tmpDir, { recursive: true, force: true });
  }
});

test('typed-observation-refusal', (t) => {
  // Given: State that cannot be observed (invalid path)
  const result = SocketTerritory.observeLinuxSocketTerritory({
    snapshotPath: '/non/existent/path/at/all',
    admissibilityPolicy: {}
  });

  // Then: Typed refusal
  assert.strictEqual(result.status, 'refused');
  assert.ok(result.reason.includes('missing observation'));

  // Forbidden: No zero measurement
  assert.notStrictEqual(result.capacity, '0', 'Should not fabricate zero');
  assert.strictEqual(result.capacity, 'UNKNOWN');
});
